","keccak256":"0xe2e337e6dde9ef6b680e07338c493ebea1b5fd09b43424112868e9cc1706bca7","license":"MIT"},"contracts/Pinkwhale/Pinkwhale.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;

import '@openzeppelin/contracts/access/Ownable.sol';

import {AdvancedOrder, CriteriaResolver, Fulfillment, Execution} from "../Seaport/lib/ConsiderationStructs.sol";
import {ItemType} from "../Seaport/lib/ConsiderationEnums.sol";

import {LoanTerms} from "./PinkwhaleStructs.sol";
import "./Utils/ERC721Utils.sol";
import "./Utils/PinkwhaleUtils.sol";
import "./Utils/SeaportUtils.sol";
import "./PinkwhaleZone.sol";

contract Pinkwhale is Ownable, PinkwhaleZone, ERC721Utils {
    event LoanExecuted(
        address executor,
        address lender,
        address borrower,
        address lienTokenAddress,
        uint256 lienTokenId,
        uint256 loanAmount,
        uint256 interest,
        uint256 expiryDate,
        uint256 pinkwhaleFee
    );

    address public feeCollector;

    constructor(address seaportAddress) SeaportUtils(seaportAddress) {
        feeCollector = msg.sender;
    }

    /**
     * @notice Create a new Loan by providing two valid Seaport Orders and terms  
     * @dev    Although there is no distinction between Orders in Seaport, we need
     *         to make a distinction to identify the Lender and Borrower, verify that
     *         the recipient of the NFTs is set as Pinkwhale and that the respective 
     *         terms are indeed matching with the hash provided in zoneHash.
     * 
     * @param lenderOrder         (Seaport specific) The Order with the NFT to collateralised set as 
     *                            consideration item and Pinkwhale set as the consideration
     *                            recipient.
     * @param borrowerOrder       (Seaport specific) The Order with the NFT to collateralised set as 
     *                            offer item.
     * @param lenderTerms         The Terms used to generate the zoneHash of the lenderOrder.
     *                            This is necessary to validate that the Terms are respected.
     * @param borrowerTerms       The Terms used to generate the zoneHash of the borrowerOrder.
     *                            This is necessary to validate that the Terms are respected.
     * @param criteriaResolvers   (Seaport specific) An array where each element contains a
     *                            reference to a specific order as well as that
     *                            order's offer or consideration, a token
     *                            identifier, and a proof that the supplied
     *                            token identifier is contained in the
     *                            order's merkle root.
     * @param fulfillments        (Seaport specific) An array of elements allocating offer
     *                            components to consideration components.
     *
     */
    function executeLoan(
        AdvancedOrder calldata lenderOrder,
        AdvancedOrder calldata borrowerOrder,
        LoanTerms calldata lenderTerms,
        LoanTerms calldata borrowerTerms,
        CriteriaResolver[] calldata criteriaResolvers,
        Fulfillment[] calldata fulfillments
    ) external {
        // Validate that all conditions are met
        require(lenderOrder.parameters.offer.length == 1, "Only one offer item is supported");
        require(lenderOrder.parameters.offer[0].itemType == ItemType.ERC20, "First Order must have a single ERC20 offer item");
        require(lenderOrder.parameters.consideration.length == 1, "Only one consideration item is supported");
        require(lenderOrder.parameters.consideration[0].itemType >= ItemType.ERC721, "First Order must have a single ERC721 consideration item");
        require(lenderOrder.parameters.consideration[0].recipient == address(this), "Recipient must be set as Pinkwhale");

        require(borrowerOrder.parameters.offer.length == 1, "Only one offer item is supported");
        require(borrowerOrder.parameters.offer[0].itemType >= ItemType.ERC721, "Second Order must have a single ERC721 offer item");
        require(borrowerOrder.parameters.consideration.length == 1, "Only one consideration item is supported");
        require(borrowerOrder.parameters.consideration[0].itemType == ItemType.ERC20, "Second Order must have a single ERC20 consideration item");

        require(_getTermsHash(lenderTerms) == lenderOrder.parameters.zoneHash, "Provided Lender terms don't match");
        require(_getTermsHash(borrowerTerms) == borrowerOrder.parameters.zoneHash, "Provided Borrower terms don't match");

        require(borrowerTerms.duration <= lenderTerms.duration, "Borrower proposed max duration cannot be bigger than Lender proposed max duration");
        require(borrowerTerms.interest >= lenderTerms.interest, "Borrower proposed max interest cannot be smaller than Lender proposed max interest");

        address lender = lenderOrder.parameters.offerer;
        address borrower = borrowerOrder.parameters.offerer;

        AdvancedOrder[] memory ordersToMatch = new AdvancedOrder[](2);
        ordersToMatch[0] = lenderOrder;
        ordersToMatch[1] = borrowerOrder;

        // Execute Orders on Seaport
        Execution[] memory executions = seaport.matchAdvancedOrders(
            ordersToMatch,
            criteriaResolvers,
            fulfillments
        );

        // Assert that execution was successful
        require(executions.length == 2, "Only two executions are supported");

        // Assert that execution order was successful. The order must be respected to generate the Resolution Orders
        require(executions[0].item.itemType == ItemType.ERC20, "First execution must be an ERC20 item");
        require(executions[1].item.itemType == ItemType.ERC721, "Second execution must be an ERC721 item");

        // The actual amount of capital borrowed
        uint256 loanAmount = executions[0].item.amount;
        address lienTokenAddress = executions[1].item.token;
        uint256 lienTokenId = executions[1].item.identifier;

        // Combine the two Order Terms to get the final Terms
        LoanTerms memory loanTerms = LoanTerms({
            interest: lenderTerms.interest, // with previous check, we guaranteed that interest is never smaller than lender interest
            duration: borrowerTerms.duration // with previous check, we guaranteed that duration is never bigger than lender duration
        });

        // We create the Resolution Orders (Repayment Order & Default Order)
        _createResolutionOrders(
            executions,
            loanTerms,
            feeCollector
        );

        // Make sure that Seaport can transferFrom the lienToken
        _approveNFT(lienTokenAddress, address(seaport));

        // Emit Event
        emit LoanExecuted(
            msg.sender,
            lender,
            borrower,
            lienTokenAddress,
            lienTokenId,
            loanAmount,
            loanTerms.interest,
            block.timestamp + loanTerms.duration,
            getPercentile(loanAmount, pinkwhaleFee)
        );
    }

    function updateFeeCollector(address newFeeCollectorAddress) public onlyOwner {
        feeCollector = newFeeCollectorAddress;
    }
}
