}","keccak256":"0x05a368ce079f61bdf70d541267bd4b8387092a383119ab57c06fb03ffa4feb41","license":"MIT"},"contracts/Pinkwhale/PinkwhaleZone.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;

import {AdvancedOrder, CriteriaResolver} from "../Seaport/lib/ConsiderationStructs.sol";
import {ZoneInterface} from "../Seaport/interfaces/ZoneInterface.sol";
import "./Utils/PinkwhaleUtils.sol";
import "./Utils/SeaportUtils.sol";

abstract contract PinkwhaleZone is ZoneInterface, SeaportUtils {
    /**
     * @notice Just throw and enforce using .isValidOrderIncludingExtraData() instead.
     *
     * @dev To validate an Order, we need the extra data (and the full Order too). 
     */
    function isValidOrder(
        bytes32,
        address,
        address,
        bytes32
    ) external pure override returns (bytes4) {
        revert("You need to provide some extra data!");
    }

    /**
     * @notice This is called by Seaport to validate an Order. 
     *         By appending the upstreamOrderHash, lienTokenAddress and lienTokenId as
     *         extraData in the Order, we can regenerate the hash and compare it to the
     *         zoneHash of the Order.
     *         We also verify that the upstreamOrderHash has not been already fulfilled, in 
     *         which case we stop the execution.
     */
    function isValidOrderIncludingExtraData(
        bytes32,
        address caller,
        AdvancedOrder calldata order,
        bytes32[] calldata,
        CriteriaResolver[] calldata
    ) external view override returns (bytes4 validOrderMagicValue) {
        bytes memory extraData = order.extraData;

        (
            bytes32 upstreamOrderHash,
            address lienTokenAddress,
            uint256 lienTokenId
        ) = abi.decode(extraData, (bytes32, address, uint256));

        _assertOrderExecution(
            order,
            upstreamOrderHash,
            caller,
            lienTokenAddress,
            lienTokenId
        );

        validOrderMagicValue = ZoneInterface.isValidOrder.selector;
    }

}
