pragma solidity ^0.8.7;

import { LoanTerms } from "../PinkwhaleStructs.sol";

contract PinkwhaleUtils {
    function generateSalt(uint256 nonce) public pure returns (bytes32) {
        return keccak256(abi.encodePacked(nonce));
    }

    function _getTermsHash(LoanTerms calldata terms) internal pure returns (bytes32 hash) {
        hash = keccak256(abi.encodePacked(
            terms.interest,
            terms.duration
        ));
    }

    function _getZoneHash(
        bytes32 upstreamOrder,
        address authorisedCaller,
        address lienTokenAddress,
        uint256 lienTokenId
    ) internal pure returns (bytes32 zoneHash) {
        zoneHash = keccak256(abi.encodePacked(
            upstreamOrder,
            authorisedCaller,
            lienTokenAddress,
            lienTokenId
        ));
    }

    /**
    * @notice Will apply a percentage to a number
    * @param number The number to multiply
    * @param percent The percentage to apply with 100_000 precision
    * @return (uint256) the operation result
    */
    function addPercentile(uint256 number, uint256 percent) public pure returns (uint256) {
        return number + getPercentile(number, percent);
    }

    /**
    * @notice Will get a percentage to a number
    * @param number The number to multiply
    * @param percent The percentage to apply with 100_000 precision
    * @return (uint256) the operation result
    */
    function getPercentile(uint256 number, uint256 percent) public pure returns (uint256) {
        return number * percent / 100_000;
    }
