pragma solidity ^0.8.7;

import {
    Order,
    OrderComponents,
    AdvancedOrder,
    CriteriaResolver,
    Execution,
    OfferItem,
    ConsiderationItem,
    OrderParameters,
    OrderStatus
} from "../../Seaport/lib/ConsiderationStructs.sol";

import {
    OrderType,
    ItemType
} from "../../Seaport/lib/ConsiderationEnums.sol";

import { SeaportInterface } from "../../Seaport/interfaces/SeaportInterface.sol";

import { LoanTerms } from "../PinkwhaleStructs.sol";
import "./PinkwhaleUtils.sol";

contract SeaportUtils is PinkwhaleUtils {
    uint256 public immutable pinkwhaleFee = 2500;

    SeaportInterface public seaport;

    constructor(address seaportAddress) {
        seaport = SeaportInterface(seaportAddress);
    }

    /**
     * @notice Create a new Seaport Order using the provided parameters.
     * @dev    This is helpful to avoid repetition of shared parameters (e.g. zone is always
     *         Pinkwhale, conduitKey is always 0x00, Order Type is always FULL_RESTRICTED, etc.)
     * 
     * @param offerItems          (Seaport specific) An array of OfferItems
     *
     * @param considerationItems  (Seaport specific) An array of ConsiderationItems
     *
     * @param startTime           The moment when the Order starts being fulfillable
     *
     * @param endTime             The moment when the Order stops being fulfillable
     *
     * @param zoneHash            The zoneHash to pass in the order
     *
     * @param salt                The salt to pass in the order
     *
     */
    function _createSeaportOrder(
        OfferItem[] memory offerItems,
        ConsiderationItem[] memory considerationItems,
        uint256 startTime,
        uint256 endTime,
        bytes32 zoneHash,
        uint256 salt
    ) internal view returns (Order memory) {
            Order memory order = Order({
            signature: '0x00',
            parameters: OrderParameters({
                offerer: address(this),
                zone: address(this),
                offer: offerItems,
                consideration: considerationItems,
                orderType: OrderType.FULL_RESTRICTED,
                startTime: startTime, 
                endTime: endTime,
                zoneHash: zoneHash,
                salt: salt,
                conduitKey: 0x00, 
                totalOriginalConsiderationItems: considerationItems.length
        })});

        return order;
    }

    /**
     * @notice Create the Repayment Order directed to the Borrower.
     * 
     * @param executions          (Seaport specific) An array of Executions returned by the
     *                            Order matching function of Seaport
     *
     * @param lender              The address of the Lender. Used to specify it as recipient of the
     *                            consideration item of the repayment
     *
     * @param borrower            The address of the Borrower. Used to specify it as the 
     *                            authorisedCaller in the zoneHash
     *
     * @param loanTerms           The final Terms used for the Loan creation. Used to specify duration 
     *                            and final amount to repay to Lender
     *
     */
    function _createSeaportRepaymentOrder(
        Execution[] memory executions,
        address lender,
        address borrower,
        LoanTerms memory loanTerms,
        address feeCollector
    ) internal view returns (Order memory) {
        OfferItem[] memory offerItems = new OfferItem[](1);
        offerItems[0] = OfferItem({
            itemType: executions[1].item.itemType,
            token: executions[1].item.token,
            identifierOrCriteria: executions[1].item.identifier,
            startAmount: 1,
            endAmount: 1
        });

        ConsiderationItem[] memory considerationItems = new ConsiderationItem[](2);
        // PAY LENDER
        considerationItems[0] = ConsiderationItem({
            itemType: executions[0].item.itemType,
            token: executions[0].item.token,
            identifierOrCriteria: executions[0].item.identifier,
            startAmount: addPercentile(executions[0].item.amount, loanTerms.interest),
            endAmount: addPercentile(executions[0].item.amount, loanTerms.interest),
            recipient: payable(lender)
        });

        // PAY PINKWHALE FEE
        considerationItems[1] = ConsiderationItem({
            itemType: executions[0].item.itemType,
            token: executions[0].item.token,
            identifierOrCriteria: executions[0].item.identifier,
            startAmount: getPercentile(executions[0].item.amount, pinkwhaleFee),
            endAmount: getPercentile(executions[0].item.amount, pinkwhaleFee),
            recipient: payable(feeCollector)
        });

        bytes32 repayOrderZoneHash = _getZoneHash(
            bytes32(0),
            borrower,
            executions[1].item.token,
            executions[1].item.identifier
        );

        // after successful execution, we create two orders and store on Seaport
        // Order 1: Allow to repay the Loan
        Order memory repayLoanOrder = _createSeaportOrder(
            offerItems,
            considerationItems,
            block.timestamp,
            block.timestamp + loanTerms.duration,
            repayOrderZoneHash,
            uint256(repayOrderZoneHash)
        );

        return repayLoanOrder;
    }

    /**
     * @notice Create the Default Order starting from a Repayment Order. This Order allows 
     *         the Lender to claim the collateralised token for free as soon as the Repayment
     *         Order expires.
     * 
     * @param repaymentOrder      The Repayment Order from which derive a Default Order.
     *
     */
    function _deriveDefaultOrderFromRepaymentOrder(
        Order memory repaymentOrder
    )
        internal
        view
        returns (Order memory)
    {
        bytes32 repaymentOrderHash = _getOrderHashFromOrder(repaymentOrder);
        address lender = repaymentOrder.parameters.consideration[0].recipient;

        bytes32 defaultOrderZoneHash = _getZoneHash(
            repaymentOrderHash,
            lender,
            repaymentOrder.parameters.offer[0].token,
            repaymentOrder.parameters.offer[0].identifierOrCriteria
        );

        // No Consideration Items means that Lender can fulfil this Order for free.
        ConsiderationItem[] memory considerationItems = new ConsiderationItem[](0);

        Order memory defaultOrder = _createSeaportOrder(
            repaymentOrder.parameters.offer,
            considerationItems,
            repaymentOrder.parameters.endTime + 1,
            repaymentOrder.parameters.endTime + 1 + 365 days,
            defaultOrderZoneHash,
            uint256(repaymentOrderHash)
        );

        return defaultOrder;
    }

    /**
     * @notice Create the Resolution Orders after a Loan has been created. 
     * 
     * @param executions          (Seaport specific) An array of Executions returned by the
     *                            Order matching function of Seaport
     *
     *
     * @param loanTerms           The final Terms used for the Loan creation. Used to specify duration 
     *                            and final amount to repay to Lender
     *
     */
    function _createResolutionOrders(
        Execution[] memory executions,
        LoanTerms memory loanTerms,
        address feeCollector
    ) internal {
        address lender = executions[0].offerer;
        address borrower = executions[1].offerer;

        // Create derived Orders
        Order memory repayLoanOrder = _createSeaportRepaymentOrder(executions, lender, borrower, loanTerms, feeCollector);
        Order memory defaultOrder = _deriveDefaultOrderFromRepaymentOrder(repayLoanOrder);

        // Validate both Orders
        Order[] memory newOrders = new Order[](2);
        newOrders[0] = repayLoanOrder;
        newOrders[1] = defaultOrder;

        seaport.validate(newOrders);
    }

    function _getOrderHashFromOrder(Order memory order) internal view returns (bytes32) {
        // Since Pinkwhale contract has no way to increase
        // counter on Seaport, we can always assume
        // the counter to be 0.
        uint256 pinkwhaleCounter = 0;

        bytes32 orderHash = seaport.getOrderHash(
            OrderComponents(
                order.parameters.offerer,
                order.parameters.zone,
                order.parameters.offer,
                order.parameters.consideration,
                order.parameters.orderType,
                order.parameters.startTime,
                order.parameters.endTime,
                order.parameters.zoneHash,
                order.parameters.salt,
                order.parameters.conduitKey,
                pinkwhaleCounter
            )
        );

        return orderHash;
    }

    /**
     * @notice This funciton is used by the .isValidOrderIncludingExtraData funciton which is called
     *         by Seaport to validate the Order execution. 
     *         In this function, we run two checks.
     *         Firstly, we guarantee that, if present, the upstreamOrderHash is not already fulfilled. 
     *         This is important because if Alice repays Bob’s Loan correctly, and then 
     *         she takes another Loan, the previous claim that Bob has is still valid. So, if the Pinkwhale contract
     *         has Alice token, Bob’s claim can be successfully fulfilled. 
     *         Secondly, we check that `hash(upstreamOrderHash, authorisedCaller, lienTokenAddress, lienTokenId)` matches
     *         with the `zoneHash` of the `order`
     * 
     * @param order               (Seaport specific) The Order to validate
     *
     * @param upstreamOrderHash   The order hash of the order that should not have been fulfilled
     *
     * @param authorisedCaller    The only address authorised to fulfill this order on Seaport. Seaport
     *                            passes this to Pinkwhale as the `caller`.
     *
     * @param lienTokenAddress    The address of the collateralised token
     *
     * @param lienTokenId         The id of the collateralised token
     *
     */
    function _assertOrderExecution(
        AdvancedOrder memory order,
        bytes32 upstreamOrderHash,
        address authorisedCaller,
        address lienTokenAddress,
        uint256 lienTokenId
    ) internal view {
        if(upstreamOrderHash != bytes32(0)) {
            // Check #1: Is the upstream order already fulfilled?
            (
                bool isValidated,
                ,
                uint256 totalFilled,
            ) = seaport.getOrderStatus(upstreamOrderHash);
            require(isValidated == true, "Order is not validated");
            require(totalFilled == 0, "Upstream Order already fulfilled");
        }

        // Check #2: do the zoneHashes match?
        bytes32 derivedZoneHash = _getZoneHash(
            upstreamOrderHash,
            authorisedCaller,
            lienTokenAddress,
            lienTokenId
        );

        require(derivedZoneHash == order.parameters.zoneHash, "ZoneHashes don't not match");
    }
}","keccak256":"0xc7d789cfd43c15c3f10a7ffe66cb01a080c267f0f376b726ea8808d781c00929","license":"MIT"},"contracts/Seaport/interfaces/SeaportInterface.sol":{"content":"// SPDX-License-Identifier: MIT
pragma solidity ^0.8.7;

import {
    BasicOrderParameters,
    OrderComponents,
    Fulfillment,
    FulfillmentComponent,
    Execution,
    Order,
    AdvancedOrder,
    OrderStatus,
    CriteriaResolver
} from "../lib/ConsiderationStructs.sol";

/**
 * @title SeaportInterface
 * @author 0age
 * @custom:version 1.1
 * @notice Seaport is a generalized ETH/ERC20/ERC721/ERC1155 marketplace. It
 *         minimizes external calls to the greatest extent possible and provides
 *         lightweight methods for common routes as well as more flexible
 *         methods for composing advanced orders.
 *
 * @dev SeaportInterface contains all external function interfaces for Seaport.
 */
interface SeaportInterface {
    /**
     * @notice Fulfill an order offering an ERC721 token by supplying Ether (or
     *         the native token for the given chain) as consideration for the
     *         order. An arbitrary number of "additional recipients" may also be
     *         supplied which will each receive native tokens from the fulfiller
     *         as consideration.
     *
     * @param parameters Additional information on the fulfilled order. Note
     *                   that the offerer must first approve this contract (or
     *                   their preferred conduit if indicated by the order) for
     *                   their offered ERC721 token to be transferred.
     *
     * @return fulfilled A boolean indicating whether the order has been
     *                   successfully fulfilled.
     */
    function fulfillBasicOrder(BasicOrderParameters calldata parameters)
        external
        payable
        returns (bool fulfilled);

    /**
     * @notice Fulfill an order with an arbitrary number of items for offer and
     *         consideration. Note that this function does not support
     *         criteria-based orders or partial filling of orders (though
     *         filling the remainder of a partially-filled order is supported).
     *
     * @param order               The order to fulfill. Note that both the
     *                            offerer and the fulfiller must first approve
     *                            this contract (or the corresponding conduit if
     *                            indicated) to transfer any relevant tokens on
     *                            their behalf and that contracts must implement
     *                            `onERC1155Received` to receive ERC1155 tokens
     *                            as consideration.
     * @param fulfillerConduitKey A bytes32 value indicating what conduit, if
     *                            any, to source the fulfiller's token approvals
     *                            from. The zero hash signifies that no conduit
     *                            should be used, with direct approvals set on
     *                            Seaport.
     *
     * @return fulfilled A boolean indicating whether the order has been
     *                   successfully fulfilled.
     */
    function fulfillOrder(Order calldata order, bytes32 fulfillerConduitKey)
        external
        payable
        returns (bool fulfilled);

    /**
     * @notice Fill an order, fully or partially, with an arbitrary number of
     *         items for offer and consideration alongside criteria resolvers
     *         containing specific token identifiers and associated proofs.
     *
     * @param advancedOrder       The order to fulfill along with the fraction
     *                            of the order to attempt to fill. Note that
     *                            both the offerer and the fulfiller must first
     *                            approve this contract (or their preferred
     *                            conduit if indicated by the order) to transfer
     *                            any relevant tokens on their behalf and that
     *                            contracts must implement `onERC1155Received`
     *                            to receive ERC1155 tokens as consideration.
     *                            Also note that all offer and consideration
     *                            components must have no remainder after
     *                            multiplication of the respective amount with
     *                            the supplied fraction for the partial fill to
     *                            be considered valid.
     * @param criteriaResolvers   An array where each element contains a
     *                            reference to a specific offer or
     *                            consideration, a token identifier, and a proof
     *                            that the supplied token identifier is
     *                            contained in the merkle root held by the item
     *                            in question's criteria element. Note that an
     *                            empty criteria indicates that any
     *                            (transferable) token identifier on the token
     *                            in question is valid and that no associated
     *                            proof needs to be supplied.
     * @param fulfillerConduitKey A bytes32 value indicating what conduit, if
     *                            any, to source the fulfiller's token approvals
     *                            from. The zero hash signifies that no conduit
     *                            should be used, with direct approvals set on
     *                            Seaport.
     * @param recipient           The intended recipient for all received items,
     *                            with `address(0)` indicating that the caller
     *                            should receive the items.
     *
     * @return fulfilled A boolean indicating whether the order has been
     *                   successfully fulfilled.
     */
    function fulfillAdvancedOrder(
        AdvancedOrder calldata advancedOrder,
        CriteriaResolver[] calldata criteriaResolvers,
        bytes32 fulfillerConduitKey,
        address recipient
    ) external payable returns (bool fulfilled);

    /**
     * @notice Attempt to fill a group of orders, each with an arbitrary number
     *         of items for offer and consideration. Any order that is not
     *         currently active, has already been fully filled, or has been
     *         cancelled will be omitted. Remaining offer and consideration
     *         items will then be aggregated where possible as indicated by the
     *         supplied offer and consideration component arrays and aggregated
     *         items will be transferred to the fulfiller or to each intended
     *         recipient, respectively. Note that a failing item transfer or an
     *         issue with order formatting will cause the entire batch to fail.
     *         Note that this function does not support criteria-based orders or
     *         partial filling of orders (though filling the remainder of a
     *         partially-filled order is supported).
     *
     * @param orders                    The orders to fulfill. Note that both
     *                                  the offerer and the fulfiller must first
     *                                  approve this contract (or the
     *                                  corresponding conduit if indicated) to
     *                                  transfer any relevant tokens on their
     *                                  behalf and that contracts must implement
     *                                  `onERC1155Received` to receive ERC1155
     *                                  tokens as consideration.
     * @param offerFulfillments         An array of FulfillmentComponent arrays
     *                                  indicating which offer items to attempt
     *                                  to aggregate when preparing executions.
     * @param considerationFulfillments An array of FulfillmentComponent arrays
     *                                  indicating which consideration items to
     *                                  attempt to aggregate when preparing
     *                                  executions.
     * @param fulfillerConduitKey       A bytes32 value indicating what conduit,
     *                                  if any, to source the fulfiller's token
     *                                  approvals from. The zero hash signifies
     *                                  that no conduit should be used, with
     *                                  direct approvals set on this contract.
     * @param maximumFulfilled          The maximum number of orders to fulfill.
     *
     * @return availableOrders An array of booleans indicating if each order
     *                         with an index corresponding to the index of the
     *                         returned boolean was fulfillable or not.
     * @return executions      An array of elements indicating the sequence of
     *                         transfers performed as part of matching the given
     *                         orders.
     */
    function fulfillAvailableOrders(
        Order[] calldata orders,
        FulfillmentComponent[][] calldata offerFulfillments,
        FulfillmentComponent[][] calldata considerationFulfillments,
        bytes32 fulfillerConduitKey,
        uint256 maximumFulfilled
    )
        external
        payable
        returns (bool[] memory availableOrders, Execution[] memory executions);

    /**
     * @notice Attempt to fill a group of orders, fully or partially, with an
     *         arbitrary number of items for offer and consideration per order
     *         alongside criteria resolvers containing specific token
     *         identifiers and associated proofs. Any order that is not
     *         currently active, has already been fully filled, or has been
     *         cancelled will be omitted. Remaining offer and consideration
     *         items will then be aggregated where possible as indicated by the
     *         supplied offer and consideration component arrays and aggregated
     *         items will be transferred to the fulfiller or to each intended
     *         recipient, respectively. Note that a failing item transfer or an
     *         issue with order formatting will cause the entire batch to fail.
     *
     * @param advancedOrders            The orders to fulfill along with the
     *                                  fraction of those orders to attempt to
     *                                  fill. Note that both the offerer and the
     *                                  fulfiller must first approve this
     *                                  contract (or their preferred conduit if
     *                                  indicated by the order) to transfer any
     *                                  relevant tokens on their behalf and that
     *                                  contracts must implement
     *                                  `onERC1155Received` to enable receipt of
     *                                  ERC1155 tokens as consideration. Also
     *                                  note that all offer and consideration
     *                                  components must have no remainder after
     *                                  multiplication of the respective amount
     *                                  with the supplied fraction for an
     *                                  order's partial fill amount to be
     *                                  considered valid.
     * @param criteriaResolvers         An array where each element contains a
     *                                  reference to a specific offer or
     *                                  consideration, a token identifier, and a
     *                                  proof that the supplied token identifier
     *                                  is contained in the merkle root held by
     *                                  the item in question's criteria element.
     *                                  Note that an empty criteria indicates
     *                                  that any (transferable) token
     *                                  identifier on the token in question is
     *                                  valid and that no associated proof needs
     *                                  to be supplied.
     * @param offerFulfillments         An array of FulfillmentComponent arrays
     *                                  indicating which offer items to attempt
     *                                  to aggregate when preparing executions.
     * @param considerationFulfillments An array of FulfillmentComponent arrays
     *                                  indicating which consideration items to
     *                                  attempt to aggregate when preparing
     *                                  executions.
     * @param fulfillerConduitKey       A bytes32 value indicating what conduit,
     *                                  if any, to source the fulfiller's token
     *                                  approvals from. The zero hash signifies
     *                                  that no conduit should be used, with
     *                                  direct approvals set on this contract.
     * @param recipient                 The intended recipient for all received
     *                                  items, with `address(0)` indicating that
     *                                  the caller should receive the items.
     * @param maximumFulfilled          The maximum number of orders to fulfill.
     *
     * @return availableOrders An array of booleans indicating if each order
     *                         with an index corresponding to the index of the
     *                         returned boolean was fulfillable or not.
     * @return executions      An array of elements indicating the sequence of
     *                         transfers performed as part of matching the given
     *                         orders.
     */
    function fulfillAvailableAdvancedOrders(
        AdvancedOrder[] calldata advancedOrders,
        CriteriaResolver[] calldata criteriaResolvers,
        FulfillmentComponent[][] calldata offerFulfillments,
        FulfillmentComponent[][] calldata considerationFulfillments,
        bytes32 fulfillerConduitKey,
        address recipient,
        uint256 maximumFulfilled
    )
        external
        payable
        returns (bool[] memory availableOrders, Execution[] memory executions);

    /**
     * @notice Match an arbitrary number of orders, each with an arbitrary
     *         number of items for offer and consideration along with as set of
     *         fulfillments allocating offer components to consideration
     *         components. Note that this function does not support
     *         criteria-based or partial filling of orders (though filling the
     *         remainder of a partially-filled order is supported).
     *
     * @param orders       The orders to match. Note that both the offerer and
     *                     fulfiller on each order must first approve this
     *                     contract (or their conduit if indicated by the order)
     *                     to transfer any relevant tokens on their behalf and
     *                     each consideration recipient must implement
     *                     `onERC1155Received` to enable ERC1155 token receipt.
     * @param fulfillments An array of elements allocating offer components to
     *                     consideration components. Note that each
     *                     consideration component must be fully met for the
     *                     match operation to be valid.
     *
     * @return executions An array of elements indicating the sequence of
     *                    transfers performed as part of matching the given
     *                    orders.
     */
    function matchOrders(
        Order[] calldata orders,
        Fulfillment[] calldata fulfillments
    ) external payable returns (Execution[] memory executions);

    /**
     * @notice Match an arbitrary number of full or partial orders, each with an
     *         arbitrary number of items for offer and consideration, supplying
     *         criteria resolvers containing specific token identifiers and
     *         associated proofs as well as fulfillments allocating offer
     *         components to consideration components.
     *
     * @param orders            The advanced orders to match. Note that both the
     *                          offerer and fulfiller on each order must first
     *                          approve this contract (or a preferred conduit if
     *                          indicated by the order) to transfer any relevant
     *                          tokens on their behalf and each consideration
     *                          recipient must implement `onERC1155Received` in
     *                          order to receive ERC1155 tokens. Also note that
     *                          the offer and consideration components for each
     *                          order must have no remainder after multiplying
     *                          the respective amount with the supplied fraction
     *                          in order for the group of partial fills to be
     *                          considered valid.
     * @param criteriaResolvers An array where each element contains a reference
     *                          to a specific order as well as that order's
     *                          offer or consideration, a token identifier, and
     *                          a proof that the supplied token identifier is
     *                          contained in the order's merkle root. Note that
     *                          an empty root indicates that any (transferable)
     *                          token identifier is valid and that no associated
     *                          proof needs to be supplied.
     * @param fulfillments      An array of elements allocating offer components
     *                          to consideration components. Note that each
     *                          consideration component must be fully met in
     *                          order for the match operation to be valid.
     *
     * @return executions An array of elements indicating the sequence of
     *                    transfers performed as part of matching the given
     *                    orders.
     */
    function matchAdvancedOrders(
        AdvancedOrder[] calldata orders,
        CriteriaResolver[] calldata criteriaResolvers,
        Fulfillment[] calldata fulfillments
    ) external payable returns (Execution[] memory executions);

    /**
     * @notice Cancel an arbitrary number of orders. Note that only the offerer
     *         or the zone of a given order may cancel it. Callers should ensure
     *         that the intended order was cancelled by calling `getOrderStatus`
     *         and confirming that `isCancelled` returns `true`.
     *
     * @param orders The orders to cancel.
     *
     * @return cancelled A boolean indicating whether the supplied orders have
     *                   been successfully cancelled.
     */
    function cancel(OrderComponents[] calldata orders)
        external
        returns (bool cancelled);

    /**
     * @notice Validate an arbitrary number of orders, thereby registering their
     *         signatures as valid and allowing the fulfiller to skip signature
     *         verification on fulfillment. Note that validated orders may still
     *         be unfulfillable due to invalid item amounts or other factors;
     *         callers should determine whether validated orders are fulfillable
     *         by simulating the fulfillment call prior to execution. Also note
     *         that anyone can validate a signed order, but only the offerer can
     *         validate an order without supplying a signature.
     *
     * @param orders The orders to validate.
     *
     * @return validated A boolean indicating whether the supplied orders have
     *                   been successfully validated.
     */
    function validate(Order[] calldata orders)
        external
        returns (bool validated);

    /**
     * @notice Cancel all orders from a given offerer with a given zone in bulk
     *         by incrementing a counter. Note that only the offerer may
     *         increment the counter.
     *
     * @return newCounter The new counter.
     */
    function incrementCounter() external returns (uint256 newCounter);

    /**
     * @notice Retrieve the order hash for a given order.
     *
     * @param order The components of the order.
     *
     * @return orderHash The order hash.
     */
    function getOrderHash(OrderComponents calldata order)
        external
        view
        returns (bytes32 orderHash);

    /**
     * @notice Retrieve the status of a given order by hash, including whether
     *         the order has been cancelled or validated and the fraction of the
     *         order that has been filled.
     *
     * @param orderHash The order hash in question.
     *
     * @return isValidated A boolean indicating whether the order in question
     *                     has been validated (i.e. previously approved or
     *                     partially filled).
     * @return isCancelled A boolean indicating whether the order in question
     *                     has been cancelled.
     * @return totalFilled The total portion of the order that has been filled
     *                     (i.e. the "numerator").
     * @return totalSize   The total size of the order that is either filled or
     *                     unfilled (i.e. the "denominator").
     */
    function getOrderStatus(bytes32 orderHash)
        external
        view
        returns (
            bool isValidated,
            bool isCancelled,
            uint256 totalFilled,
            uint256 totalSize
        );

    /**
     * @notice Retrieve the current counter for a given offerer.
     *
     * @param offerer The offerer in question.
     *
     * @return counter The current counter.
     */
    function getCounter(address offerer)
        external
        view
        returns (uint256 counter);

    /**
     * @notice Retrieve configuration information for this contract.
     *
     * @return version           The contract version.
     * @return domainSeparator   The domain separator for this contract.
     * @return conduitController The conduit Controller set for this contract.
     */
    function information()
        external
        view
        returns (
            string memory version,
            bytes32 domainSeparator,
            address conduitController
        );

    /**
     * @notice Retrieve the name of this contract.
     *
     * @return contractName The name of this contract.
     */
    function name() external view returns (string memory contractName);
}
